import React, { useEffect, useState } from "react";
import "./index.scss";


// Reuse the same icon filenames you already have in /public/tech-icons
const techIconMap = {
  react: "/tech-icons/react.svg",
  nextjs: "/tech-icons/nextjs.png",
  javascript: "/tech-icons/javascript.png",
  typescript: "/tech-icons/typescript.png",
  node: "/tech-icons/nodejs.png",
  api: "/tech-icons/api.png",
  mongodb: "/tech-icons/mongodb.svg",
  css: "/tech-icons/css.svg",
  tailwind: "/tech-icons/tailwind.png",
  google: "/tech-icons/google.png",
  facebook: "/tech-icons/facebook.png",
  geolocation: "/tech-icons/geolocation.png",
};

const techList = [
  ["react", "React"],
  ["nextjs", "Next.js"],
  ["typescript", "TypeScript"],
  ["javascript", "JavaScript"],
  ["node", "Node.js"],
  ["mongodb", "MongoDB"],
  ["css", "CSS / SCSS"],
  ["api", "REST APIs"],
];

const About = () => {
  const [letterClass, setLetterClass] = useState("text-animate");
  // const [ref, inView] = useInView();

  useEffect(() => {
    const timer = setTimeout(() => {
      setLetterClass("text-animate-hover");
    }, 3000);
    return () => clearTimeout(timer);
  }, []);

  return (
    <div
      id="about"
      ref={ref}
      className={`container about-page fade-section ${
        inView ? "in-view" : ""
      }`}
    >
      <h1 className="page-title">
        {/* <AnimatedLetters
          letterClass={letterClass}
          strArray={"About Me:".split("")}
          index={15}
        /> */}
      </h1>

      {/* Top text block */}
      <div className="about-grid">
        <div className="about-copy">
          <p>
            I&apos;m Chris, a full-stack web developer based in New York City
            who likes turning messy, real-world problems into clean, thoughtful
            web apps.
          </p>
          <p>
            Most of my work centers around{" "}
            <span className="highlight">React</span>,{" "}
            <span className="highlight">Next.js</span>, and{" "}
            <span className="highlight">TypeScript</span> — building
            data-driven tools like fantasy sports optimizers, smarter fitness
            tracking, and utilities for the Pokémon TCG. I care a lot about
            clear UX, performance, and writing code that&apos;s easy for the
            next developer to understand.
          </p>
        </div>

        <div className="about-copy">
          <p>
            Right now I&apos;m focused on sharpening my back-end skills with{" "}
            <span className="highlight">Node</span>,{" "}
            <span className="highlight">APIs</span>, and{" "}
            <span className="highlight">MongoDB</span>, and growing into a role
            where I can ship production features, learn from more senior
            engineers, and contribute to a strong engineering culture.
          </p>
          <p>
            Outside of coding you&apos;ll usually find me competing in the
            Pokémon TCG, teaching chess to elementary school students, or
            lifting at the gym.
          </p>
        </div>
      </div>

      {/* Bottom cards */}
      <div className="about-cards">
        <section className="about-card">
          <h2 className="card-title">Problems I&apos;m Solving</h2>
          <ul>
            <li>Shipping small, end-to-end features in real projects</li>
            <li>Deepening my TypeScript and testing habits</li>
            <li>Designing clean, predictable API contracts</li>
            <li>
              Leveling up in performance, accessibility, and developer
              experience
            </li>
          </ul>
        </section>

        <section className="about-card">
          <h2 className="card-title">Tech I Work With</h2>
          <div className="tech-pill-row">
            {techList.map(([key, label]) => (
              <div key={key} className="tech-pill">
                <img src={techIconMap[key]} alt={label} />
                <span>{label}</span>
              </div>
            ))}
          </div>
        </section>
      </div>
    </div>
  );
};

export default About;
